    return (h or '').strip().lstrip('\ufeff').strip()


users = []
with open(USERS, newline='', encoding='utf-8-sig') as f:
    reader = csv.DictReader(f)
    reader.fieldnames = [norm_header(h) for h in reader.fieldnames]
    for row in reader:
        row = {k: (v or '').strip() for k, v in row.items() if k is not None}
        users.append(row)

by_id = {}
for u in users:
    by_id[u['id']] = u

totals = {uid: Decimal('0') for uid in by_id}


def pick(d, names):
    for n in names:
        if n in d:
            return d[n]
    return None


def to_dec(v):
    if isinstance(v, (int, float)):
        return Decimal(str(v))
    s = str(v).strip().replace(',', '')
    for ch in ('$', '\u20ac', '\u00a3'):
        s = s.replace(ch, '')
    return Decimal(s)


first = True
with open(ORDERS, encoding='utf-8-sig') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        if first:
            print('order keys:', sorted(o.keys()), file=sys.stderr)
            first = False
        uid = pick(o, ['user_id', 'userId', 'user', 'uid'])
        status = pick(o, ['status', 'state'])
        total = pick(o, ['total', 'amount', 'total_amount'])
        if uid is None or status is None or total is None:
            print('skipping order missing fields:', o, file=sys.stderr)
            continue
        uid = str(uid).strip()
        if uid not in by_id:
            continue
        if str(status).strip() == 'paid':
            totals[uid] += to_dec(total)

report = []
for uid, u in by_id.items():
    t = totals[uid].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    report.append({'user': u['name'], 'country': u['country'], 'paid_total': float(t)})

report.sort(key=lambda r: (-r['paid_total'], r['user']))

with open(OUT, 'w', encoding='utf-8') as f:
    json.dump(report, f, indent=2)
    f.write('\n')

print(json.dumps(report, indent=2))
